import { useId, type ReactElement, type ReactNode } from "react";
import {
    Popover, PopoverContent, PopoverTrigger, PopoverClose,
} from "./popover";

type CoachmarkProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    trigger: ReactElement;
    title: string;
    children: ReactNode;
    step?: number;
    totalSteps?: number;
    nextAction?: { label: string; onClick: () => void };
    closeLabel?: string;
    side?: "top" | "right" | "bottom" | "left";
    container?: HTMLElement | null;
};

function Coachmark({
    open, onOpenChange, trigger, title, children, step, totalSteps,
    nextAction, closeLabel = "도움말 닫기", side = "bottom", container,
}: CoachmarkProps) {
    const titleId = useId();
    const descriptionId = useId();
    if ((step !== undefined || totalSteps !== undefined) &&
        (typeof step !== "number" || typeof totalSteps !== "number" ||
            !Number.isSafeInteger(step) || !Number.isSafeInteger(totalSteps) ||
            step < 1 || totalSteps < step)) {
        throw new RangeError("Coachmark step must be within totalSteps.");
    }
    return (
        <Popover open={open} onOpenChange={onOpenChange} modal={false}>
            <PopoverTrigger asChild>{trigger}</PopoverTrigger>
            <PopoverContent container={container} side={side} sideOffset={10}
                role="dialog" aria-labelledby={titleId}
                aria-describedby={descriptionId} data-coachmark="">
                {step !== undefined && <p className="m-0 mb-2 text-xs text-muted">
                    {step} / {totalSteps} 단계
                </p>}
                <h3 id={titleId} className="m-0 text-sm font-semibold">{title}</h3>
                <div id={descriptionId} className="mt-2 text-sm text-muted">
                    {children}
                </div>
                <div className="mt-4 flex flex-wrap items-center justify-end gap-2">
                    <PopoverClose asChild>
                        <button type="button" className={
                            "rounded-sm px-3 py-1.5 text-sm text-muted " +
                            "hover:bg-surface-subtle focus-visible:outline-2 " +
                            "focus-visible:outline-focus"
                        }>{closeLabel}</button>
                    </PopoverClose>
                    {nextAction && <button type="button"
                        onClick={nextAction.onClick} className={
                            "rounded-sm bg-accent px-3 py-1.5 text-sm " +
                            "font-medium text-accent-foreground " +
                            "focus-visible:outline-2 focus-visible:outline-focus"
                        }>{nextAction.label}</button>}
                </div>
            </PopoverContent>
        </Popover>
    );
}

export { Coachmark };
export type { CoachmarkProps };
